import re

def parse_amount(raw):
    s = raw.strip()

    if not s:
        return None

    is_negative = False
    if s.startswith('(') and s.endswith(')'):
        is_negative = True
        s = s[1:-1].strip()

    if s.startswith('-'):
        is_negative = not is_negative
        s = s[1:].strip()
    elif s.startswith('+'):
        s = s[1:].strip()

    if s.startswith('\$'):
        s = s[1:].strip()

    m = re.fullmatch(r'(\d+)(?:\.(\d{1,2}))?', s)
    print(f'  raw={raw!r} -> stripped={s!r}, match={m}')
    if not m:
        return None

    dollars_str, cents_str = m.group(1), m.group(2)

    if cents_str is None:
        cents_str = '00'
    else:
        cents_str = cents_str.ljust(2, '0')[:2]

    total_cents = int(dollars_str) * 100 + int(cents_str)

    if is_negative:
        total_cents = -total_cents

    return total_cents

print(parse_amount('\$2,047.48'))
